import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';
import { Line } from 'react-chartjs-2';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

export default function App() {
  const [coins, setCoins] = useState([]);
  const [search, setSearch] = useState('');
  const [filteredCoins, setFilteredCoins] = useState([]);
  const [selectedCoin, setSelectedCoin] = useState('bitcoin');
  const [coinData, setCoinData] = useState(null);
  const [history, setHistory] = useState([]);
  const [predictedPrice, setPredictedPrice] = useState(null);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [intervalMonths, setIntervalMonths] = useState(3);
  const [offsetMonths, setOffsetMonths] = useState(0);

  const inputRef = useRef(null);

  useEffect(() => {
    async function fetchCoins() {
      try {
        const res = await axios.get('https://api.coingecko.com/api/v3/coins/list');
        setCoins(res.data);
      } catch (error) {
        console.error('Error fetching coin list:', error);
      }
    }
    fetchCoins();
  }, []);

  useEffect(() => {
    if (!selectedCoin) return;

    async function fetchCoinInfo() {
      try {
        const res = await axios.get(`https://api.coingecko.com/api/v3/coins/${selectedCoin}`);
        setCoinData(res.data);
      } catch (error) {
        console.error('Error fetching coin info:', error);
      }
    }

    async function fetchHistory() {
      try {
        const res = await axios.get(`https://api.coingecko.com/api/v3/coins/${selectedCoin}/market_chart`, {
          params: { vs_currency: 'usd', days: 365 }
        });
        setHistory(res.data.prices);
        predictPrice(res.data.prices.map(p => p[1]));
        setOffsetMonths(0);
      } catch (error) {
        console.error('Error fetching coin history:', error);
      }
    }

    fetchCoinInfo();
    fetchHistory();
  }, [selectedCoin]);

  const predictPrice = (prices) => {
    if (prices.length === 0) {
      setPredictedPrice(null);
      return;
    }
    const x = prices.map((_, i) => i);
    const y = prices;
    const n = x.length;
    const sumX = x.reduce((a, b) => a + b, 0);
    const sumY = y.reduce((a, b) => a + b, 0);
    const sumXY = x.reduce((sum, xi, i) => sum + xi * y[i], 0);
    const sumX2 = x.reduce((sum, xi) => sum + xi * xi, 0);

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    const prediction = slope * n + intercept;
    setPredictedPrice(prediction.toFixed(2));
  };

  const handleSearchChange = (e) => {
    const val = e.target.value;
    setSearch(val);

    if (val.trim() === '') {
      setFilteredCoins([]);
      setShowSuggestions(false);
      return;
    }

    const filtered = coins
      .filter(c => c.name.toLowerCase().includes(val.toLowerCase()))
      .slice(0, 10);
    setFilteredCoins(filtered);
    setShowSuggestions(true);
  };

  const handleSelectCoin = (coinId, coinName) => {
    setSelectedCoin(coinId);
    setSearch(coinName);
    setShowSuggestions(false);
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (inputRef.current && !inputRef.current.contains(event.target)) {
        setShowSuggestions(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const monthsToDays = (m) => m * 30;

  const daysInterval = monthsToDays(intervalMonths);
  const totalDays = history.length;
  const startIndex = Math.max(0, totalDays - (offsetMonths + 1) * daysInterval);
  const endIndex = totalDays - offsetMonths * daysInterval;
  const windowData = history.slice(startIndex, endIndex);

  const pricesInWindow = windowData.map(p => p[1]);
  const minPrice = pricesInWindow.length > 0 ? Math.min(...pricesInWindow) : null;
  const maxPrice = pricesInWindow.length > 0 ? Math.max(...pricesInWindow) : null;

  const chartData = {
    labels: windowData.map(p => new Date(p[0]).toLocaleDateString()),
    datasets: [
      {
        label: `${coinData?.name || ''} Price (USD)`,
        data: pricesInWindow,
        borderColor: 'rgba(75,192,192,1)',
        backgroundColor: 'rgba(75,192,192,0.2)',
        fill: true,
        tension: 0.3,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: { position: 'top' },
      title: { display: true, text: `Price History (Last ${intervalMonths} Months)` },
    },
    scales: { y: { beginAtZero: false } },
  };

  return (
    <div style={{ maxWidth: 700, margin: 'auto', fontFamily: 'Arial, sans-serif', padding: 20 }}>
      <h1 style={{ marginBottom: 20 }}>Crypto Coin Predictor Using AI</h1>

      {/* Search bar */}
      <div style={{ position: 'relative' }} ref={inputRef}>
        <input
          type="text"
          value={search}
          onChange={handleSearchChange}
          placeholder="Search coins..."
          style={{ width: '100%', padding: 8, fontSize: 16 }}
          onFocus={() => {
            if (filteredCoins.length > 0) setShowSuggestions(true);
          }}
        />
        {showSuggestions && filteredCoins.length > 0 && (
          <ul
            style={{
              position: 'absolute',
              top: '100%',
              left: 0,
              right: 0,
              border: '1px solid #ccc',
              maxHeight: 200,
              overflowY: 'auto',
              backgroundColor: 'white',
              margin: 0,
              padding: 0,
              listStyle: 'none',
              zIndex: 1000
            }}
          >
            {filteredCoins.map(c => (
              <li
                key={c.id}
                style={{ padding: 8, cursor: 'pointer' }}
                onClick={() => handleSelectCoin(c.id, c.name)}
              >
                {c.name}
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Interval dropdown */}
      <div style={{ marginTop: 20 }}>
        <label>
          Select Interval:{' '}
          <select
            value={intervalMonths}
            onChange={(e) => {
              setIntervalMonths(Number(e.target.value));
              setOffsetMonths(0);
            }}
            style={{ padding: 6, fontSize: 16 }}
          >
            <option value={3}>3 Months</option>
            <option value={6}>6 Months</option>
            <option value={12}>12 Months</option>
          </select>
        </label>
      </div>

      {/* Navigation Buttons */}
      <div style={{ marginTop: 15 }}>
        <button
          disabled={offsetMonths >= Math.floor(365 / daysInterval)}
          onClick={() => setOffsetMonths(offsetMonths + 1)}
          style={{ marginRight: 10, padding: '6px 12px' }}
        >
          Next Window
        </button>
        <button
          disabled={offsetMonths <= 0}
          onClick={() => setOffsetMonths(Math.max(0, offsetMonths - 1))}
          style={{ padding: '6px 12px' }}
        >
          Previous Window
        </button>
      </div>

      {/* Coin Info */}
      {coinData && (
        <div style={{ marginTop: 25 }}>
          <h2>{coinData.name}</h2>
          <p>Current Price: ${coinData.market_data.current_price.usd}</p>
          <p>
            24h Change: {coinData.market_data.price_change_percentage_24h >= 0 ? '+' : '-'}
            {Math.abs(coinData.market_data.price_change_percentage_24h).toFixed(2)}%
          </p>
          <p>Predicted Price (next day): ${predictedPrice}</p>
          {minPrice !== null && maxPrice !== null && (
            <p>Price range for this window: ${minPrice.toFixed(2)} - ${maxPrice.toFixed(2)}</p>
          )}
        </div>
      )}

      {/* Chart */}
      {windowData.length > 0 && (
        <div style={{ marginTop: 20 }}>
          <Line data={chartData} options={chartOptions} />
        </div>
      )}
    </div>
  );
}
